mapper.select:
SELECT n.id, n.type, n.union_id, n.product_key, n.name, n.description, n.create_date, n.create_user, n.tenant_id, n.state, n.configuration, CASE WHEN n.type = 'TCP_CLIENT' THEN 'TCP客户端' WHEN n.type = 'TCP_SERVER' THEN 'TCP服务端' WHEN n.type = 'UDP' THEN 'UDP服务' WHEN n.type = 'MQTT_CLIENT' THEN 'MQTT客户端' WHEN n.type = 'MQTT_SERVER' THEN 'MQTT服务端' ELSE n.type END as type_name, CASE WHEN n.state = 1 THEN '启动' ELSE '关闭' END as state_name, to_char(n.create_date, 'YYYY-MM-DD HH24:MI:SS') as create_date_str FROM iot_network n
AND n.type IN
#{typeItem}
AND n.name LIKE CONCAT('%', #{name}, '%')
AND n.product_key = #{productKey}
AND n.state = #{state}
AND n.union_id = #{unionId}
AND ( n.tenant_id = #{tenantId}
OR ((n.tenant_id IS NULL OR n.tenant_id = '') AND n.create_user IN
#{scopeUnionId}
)
)
AND 1 = 0
AND n.create_user IN
#{scopeUnionId}
ORDER BY n.create_date DESC

mapper.update:
