type = #{type}, union_id = #{unionId}, product_key = #{productKey}, name = #{name}, description = #{description}, tenant_id = #{tenantId}, state = #{state}, configuration = #{configuration},
WHERE id = #{id}

UPDATE iot_network
SET state = #{state}
WHERE id = #{id}

